import hashlib
import json
from pathlib import Path


def load_packet(path="packet.json"):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def _require_key(record, key):
    if key not in record:
        raise ValueError(f'{record.get("id", "UNKNOWN")}: missing field {key}')
    return record[key]


def _require_integer(value, field, record_id):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f'{record_id}: {field} must be an integer or null')


def check_record(record):
    if not isinstance(record, dict):
        raise ValueError("record must be an object")
    record_id = record.get("id", "UNKNOWN")
    if not isinstance(record_id, str) or not record_id:
        raise ValueError("record id must be a nonempty string")

    correct = _require_key(record, "correct")
    eligible = _require_key(record, "eligible")
    reported = _require_key(record, "reported_percent")

    if correct is not None:
        _require_integer(correct, "correct", record_id)
        if correct < 0:
            raise ValueError(
                f'{record_id}: invalid counts: correct must be 0..eligible and eligible must be positive'
            )

    if eligible is not None:
        _require_integer(eligible, "eligible", record_id)
        if eligible <= 0:
            raise ValueError(
                f'{record_id}: invalid counts: correct must be 0..eligible and eligible must be positive'
            )

    if correct is not None and eligible is not None and correct > eligible:
        raise ValueError(
            f'{record_id}: invalid counts: correct must be 0..eligible and eligible must be positive'
        )

    if correct is None or eligible is None:
        return f'{record_id}: accuracy=UNKNOWN (missing numerator or denominator)'

    _require_integer(reported, "reported_percent", record_id)
    calculated = round(correct / eligible * 100)
    if calculated != reported:
        raise ValueError(
            f'{record_id}: reported {reported}% does not match calculated {calculated}%'
        )
    return f'{record_id}: accuracy={calculated}% ({correct}/{eligible})'


def verify_fidelity(packet):
    token = packet.get("fidelity_token")
    supplied = packet.get("fidelity_sha256")
    if not isinstance(token, str) or not isinstance(supplied, str):
        raise ValueError("fidelity token and digest must be strings")
    actual = hashlib.sha256(token.encode("utf-8")).hexdigest()
    if actual != supplied:
        raise ValueError("fidelity digest mismatch")
    return "fidelity: MATCH"


if __name__ == "__main__":
    packet = load_packet()
    for record in packet["records"]:
        print(check_record(record))
    print(verify_fidelity(packet))

import hashlib
import unittest

from verify import check_record, verify_fidelity


class VerificationTests(unittest.TestCase):
    def test_positive_arithmetic(self):
        record = {"id": "POS", "correct": 8, "eligible": 10, "reported_percent": 80}
        self.assertEqual(check_record(record), "POS: accuracy=80% (8/10)")

    def test_positive_round_half_even(self):
        record = {"id": "TIE", "correct": 1, "eligible": 40, "reported_percent": 2}
        self.assertEqual(check_record(record), "TIE: accuracy=2% (1/40)")

    def test_unknown_missing_counts(self):
        record = {"id": "UNK", "correct": None, "eligible": None, "reported_percent": 82}
        self.assertEqual(
            check_record(record),
            "UNK: accuracy=UNKNOWN (missing numerator or denominator)",
        )

    def test_negative_wrong_reported_percentage(self):
        record = {"id": "BADPCT", "correct": 8, "eligible": 10, "reported_percent": 82}
        with self.assertRaisesRegex(ValueError, "does not match"):
            check_record(record)

    def test_negative_invalid_counts(self):
        record = {"id": "BADCOUNT", "correct": 11, "eligible": 10, "reported_percent": 110}
        with self.assertRaisesRegex(ValueError, "invalid counts"):
            check_record(record)

    def test_negative_boolean_count(self):
        record = {"id": "BOOL", "correct": True, "eligible": 10, "reported_percent": 10}
        with self.assertRaisesRegex(ValueError, "must be an integer"):
            check_record(record)

    def test_negative_fractional_count(self):
        record = {"id": "FRACTION", "correct": 1.5, "eligible": 2, "reported_percent": 75}
        with self.assertRaisesRegex(ValueError, "must be an integer"):
            check_record(record)

    def test_negative_string_count(self):
        record = {"id": "STRING", "correct": "8", "eligible": 10, "reported_percent": 80}
        with self.assertRaisesRegex(ValueError, "must be an integer"):
            check_record(record)

    def test_negative_malformed_record(self):
        record = {"id": "MISSING", "correct": 8, "eligible": 10}
        with self.assertRaisesRegex(ValueError, "missing field reported_percent"):
            check_record(record)

    def test_negative_digest(self):
        packet = {
            "fidelity_token": "abc",
            "fidelity_sha256": hashlib.sha256(b"not-abc").hexdigest(),
        }
        with self.assertRaisesRegex(ValueError, "digest mismatch"):
            verify_fidelity(packet)

    def test_one_null_valid_missing_eligible(self):
        record = {"id": "NO_DENOM", "correct": 0, "eligible": None, "reported_percent": 0}
        self.assertEqual(
            check_record(record),
            "NO_DENOM: accuracy=UNKNOWN (missing numerator or denominator)",
        )

    def test_one_null_valid_missing_correct(self):
        record = {"id": "NO_NUM", "correct": None, "eligible": 1, "reported_percent": 0}
        self.assertEqual(
            check_record(record),
            "NO_NUM: accuracy=UNKNOWN (missing numerator or denominator)",
        )

    def test_one_null_invalid_negative_correct(self):
        record = {"id": "NEG_NUM", "correct": -1, "eligible": None, "reported_percent": 0}
        with self.assertRaisesRegex(ValueError, "invalid counts"):
            check_record(record)

    def test_one_null_invalid_nonpositive_eligible(self):
        records = [
            {"id": "ZERO_DENOM", "correct": None, "eligible": 0, "reported_percent": 0},
            {"id": "NEG_DENOM", "correct": None, "eligible": -2, "reported_percent": 0},
        ]
        for record in records:
            with self.subTest(record_id=record["id"]):
                with self.assertRaisesRegex(ValueError, "invalid counts"):
                    check_record(record)


if __name__ == "__main__":
    unittest.main()
